mapper.select:

SELECT like_id AS likeId, post_id AS postId, user_id AS userId
FROM likes
WHERE post_id = #{postId}
  AND user_id = #{userId}

mapper.update:

UPDATE posts
SET like_count = like_count + 1
WHERE post_id = #{postId}

mapper.delete:

DELETE FROM likes
WHERE post_id = #{postId}
  AND user_id = #{userId}

mapper.update:

UPDATE posts
SET like_count = like_count - 1
WHERE post_id = #{postId}
